{
  "name": "VISA通信器",
  "name_en": "VISA Communicator",
  "manufacturer": "",
  "description": "非物理软件通信组件，将 VISA/pyVISA 连接封装为类文件对象，用于在实验系统中按资源名访问兼容 VISA 的仪器会话，并管理原始字节读写、终止符、超时和输入缓冲区。",
  "description_en": "A non-physical software communication component that exposes a VISA/pyVISA connection as a file-like object for laboratory systems. It is used to access VISA-compatible instrument sessions by resource name and manage raw byte I/O, termination settings, timeouts, and input-buffer handling.",
  "actions": [
    {
      "action_name": "auto-address",
      "description": "获取/设置/定义VISA资源地址",
      "description_en": "get/set/define the VISA resource address"
    },
    {
      "action_name": "auto-close",
      "description": "关闭VISA连接",
      "description_en": "close the VISA connection"
    },
    {
      "action_name": "auto-flush_input",
      "description": "清空并丢弃输入缓冲区内容",
      "description_en": "flush and discard the input buffer contents"
    },
    {
      "action_name": "auto-read_raw",
      "description": "从VISA连接读取原始字节数据",
      "description_en": "read raw bytes from the VISA connection"
    },
    {
      "action_name": "auto-read_termination",
      "description": "获取/设置/定义读取终止符",
      "description_en": "get/set/define the read termination"
    },
    {
      "action_name": "auto-seek",
      "description": "设置当前类文件缓冲位置",
      "description_en": "set the current file-like buffer position"
    },
    {
      "action_name": "auto-tell",
      "description": "获取当前类文件缓冲位置",
      "description_en": "get the current file-like buffer position"
    },
    {
      "action_name": "auto-terminator",
      "description": "获取/设置/定义VISA终止字符",
      "description_en": "get/set/define the VISA termination character"
    },
    {
      "action_name": "auto-timeout",
      "description": "获取/设置/定义通信超时时间",
      "description_en": "get/set/define the communication timeout"
    },
    {
      "action_name": "auto-write_raw",
      "description": "向VISA连接写入原始字节数据",
      "description_en": "write raw bytes to the VISA connection"
    },
    {
      "action_name": "auto-write_termination",
      "description": "获取/设置/定义写入终止符",
      "description_en": "get/set/define the write termination"
    }
  ],
  "tag_hints": [
    "VISA communication",
    "pyVISA",
    "instrument session I/O",
    "raw byte read/write",
    "termination settings",
    "timeout control",
    "input buffer management"
  ]
}

